ROOT=Path(__file__).resolve().parent

def scene(sid, beat, shot, focal, objects, text, purpose, question, relation, payoff, choice, evidence='Fiksi — adegan dan dialog rekaan; bukan data atau kutipan kejadian nyata.'):
    return dict(id=sid,beat=beat,shot=shot,focal=focal,
      objects=[{'object':x,'action':y} for x,y in objects],text=text,purpose=purpose,
      viewerQuestion=question,connection=relation,nextOrPayoff=payoff,wordChoice=choice,evidence=evidence)

def S(n,b,shot,focal,objects,text,purpose,question,relation,payoff,choice,evidence=None):
    args=(f'S{n:02}' if isinstance(n,int) else f'S{n}',b,shot,focal,objects,text,purpose,question,relation,payoff,choice)
    return scene(*args,**({'evidence':evidence} if evidence else {}))

def T(n,b,shot,focal,objects,text,purpose,question,relation,payoff,choice,evidence=None):
    args=(f'T{n:02}' if isinstance(n,int) else f'T{n}',b,shot,focal,objects,text,purpose,question,relation,payoff,choice)
    return scene(*args,**({'evidence':evidence} if evidence else {}))

