def package(items,name,script_id):
 script={'id':script_id,'status':'DRAF REVISI PRIVAT — arah mendapat tanggapan positif dengan koreksi; naskah, prevoice dan tayang belum disetujui',
         'scenes':[{'id':s['id'],'narration':s['text']} for s in items]}
 audit={'scriptId':script_id,'audienceAnchor':{'situation':'Di grup bersama, sebuah usul bergeser menjadi pembahasan orang yang mengirimkannya.',
         'scope':'Seluruh tokoh dan kejadian fiktif. Tidak semua informasi tentang seseorang tidak relevan; tidak ada diagnosis psikologis.'},
        'items':[{'sceneId':s['id'],'text':s['text'],'purpose':s['purpose'],'viewerQuestion':s['viewerQuestion'],
                  'connection':s['connection'],'visualAction':s['shot']+' '+ '; '.join(x['object']+' → '+x['action'] for x in s['objects']),
                  'evidence':s['evidence'],'nextOrPayoff':s['nextOrPayoff'],'wordChoice':s['wordChoice']} for s in items]}
 for suffix,data in [('script',script),('audit',audit)]:
  (ROOT/f'{name}.{suffix}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 heading='Master' if name=='master' else 'Short'
 md=[f'# Naskah {heading} — Tangga Itu Masih Licin','','DRAF REVISI PRIVAT. Nara, Bima, tempat dan kejadian adalah fiksi.','','']
 for s in items:md.extend([f"## {s['id']}",s['text'],''])
 (ROOT/f'naskah-{name}.md').write_text('\n'.join(md),encoding='utf-8')
 board=[f'# Storyboard {heading} — Tangga Itu Masih Licin','','DRAF: objek, sudut dan durasi perlu diuji pada animatic; CTA generik sengaja tidak disisipkan.','','| Scene | Beat | Narasi | Fokus & aksi | ObjectMap |','|---|---|---|---|---|']
 for s in items:board.append(f"| {s['id']} | {s['beat']} | {s['text']} | {s['shot']} Fokus: {s['focal']}. | "+'; '.join(x['object']+' → '+x['action'] for x in s['objects'])+' |')
 (ROOT/f'storyboard-{name}.md').write_text('\n'.join(board)+'\n',encoding='utf-8')

package(master,'master',brief['scriptId']);package(short,'short','tangga-masih-licin-short-v2')
(ROOT/'brief.json').write_text(json.dumps(brief,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
meta={name:[{'id':s['id'],'beat':s['beat'],'shot':s['shot'],'focal':s['focal'],'objectMap':s['objects'], **({'sourceSceneIds':short_sources[s['id']]} if name=='short' else {})} for s in items] for name,items in [('master',master),('short',short)]}
(ROOT/'render-meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(ROOT/'short-sumber-master.json').write_text(json.dumps(short_sources,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
